 String[] types(){return new String[]{"upnp:rootdevice",uuid,"urn:schemas-upnp-org:device:MediaRenderer:1",urn("avt"),urn("rc"),urn("cm")};}String usn(String type){return type.equals(uuid)?uuid:uuid+"::"+type;}
