 void discover(){byte[] buffer=new byte[8192];HashMap<String,Long> recent=new HashMap<>();while(running)try{DatagramPacket packet=new DatagramPacket(buffer,buffer.length);discovery.receive(packet);if(!packet.getAddress().isSiteLocalAddress())continue;String message=new String(packet.getData(),packet.getOffset(),packet.getLength(),"UTF-8");if(!message.startsWith("M-SEARCH "))continue;String peer=packet.getAddress().getHostAddress();long now=System.currentTimeMillis();if(recent.containsKey(peer)&&now-recent.get(peer)<500)continue;if(recent.size()>128)recent.clear();recent.put(peer,now);String wanted="";for(String line:message.split("[\r\n]+"))if(line.toLowerCase(Locale.US).startsWith("st:"))wanted=line.substring(3).trim();for(String type:types())if(wanted.equals("ssdp:all")||wanted.equals(type)){String response="HTTP/1.1 200 OK\r\nCACHE-CONTROL: max-age=180\r\nEXT:\r\nLOCATION: "+base+"/device.xml\r\nSERVER: Android/4.2 UPnP/1.0 SkyFamily/0.9\r\nST: "+type+"\r\nUSN: "+usn(type)+"\r\n\r\n";byte[] data=response.getBytes("UTF-8");discovery.send(new DatagramPacket(data,data.length,packet.getAddress(),packet.getPort()));}}catch(SocketTimeoutException ignored){}catch(Exception ignored){}}
