 static Map<String,String> parse(String xml)throws Exception{if(xml.toUpperCase(Locale.US).contains("<!DOCTYPE"))throw new IOException("DOCTYPE disabled");XmlPullParser p=Xml.newPullParser();p.setFeature(XmlPullParser.FEATURE_PROCESS_NAMESPACES,true);p.setInput(new StringReader(xml));HashMap<String,String> result=new HashMap<>();String key="";int events=0;for(int e=p.getEventType();e!=XmlPullParser.END_DOCUMENT;e=p.next()){if(++events>10000||p.getDepth()>64)throw new IOException("XML limit");if(e==XmlPullParser.START_TAG)key=p.getName();else if(e==XmlPullParser.TEXT)result.put(key,result.containsKey(key)?result.get(key)+p.getText():p.getText());else if(e==XmlPullParser.END_TAG)key="";}return result;}
 synchronized Map<String,String> act(String id,String action,Map<String,String> a)throws Exception{if(a.containsKey("InstanceID")&&!a.get("InstanceID").trim().equals("0"))throw new IOException();if(a.containsKey("Channel")&&!a.get("Channel").trim().equals("Master"))throw new IOException();HashMap<String,String> r=new HashMap<>();if(action.equals("SetAVTransportURI")){String value=a.get("CurrentURI");if(value==null||value.length()>4096)throw new IOException();URI u=new URI(value);if(!("http".equalsIgnoreCase(u.getScheme())||"https".equalsIgnoreCase(u.getScheme()))||u.getHost()==null||u.getUserInfo()!=null)throw new IOException();uri=value;metadata=a.containsKey("CurrentURIMetaData")?a.get("CurrentURIMetaData"): "";position=duration=0;wantPlay=false;state="TRANSITIONING";status="OK";sink.command(action,new HashMap<>(a));}else if(action.equals("Play")){if(uri.isEmpty()||!"1".equals(a.get("Speed")))throw new IOException();wantPlay=true;if(!state.equals("TRANSITIONING"))state="PLAYING";sink.command(action,a);}else if(action.equals("Pause")||action.equals("Stop")){wantPlay=false;state=action.equals("Pause")?"PAUSED_PLAYBACK":"STOPPED";if(action.equals("Stop"))position=0;sink.command(action,a);}else if(action.equals("Seek")){if(!"REL_TIME".equals(a.get("Unit"))&&!"ABS_TIME".equals(a.get("Unit")))throw new IOException();position=parseTime(a.get("Target"));sink.command(action,a);}else if(action.equals("SetVolume")){int n=Integer.parseInt(a.get("DesiredVolume"));if(n<0||n>100)throw new IOException();volume=n;sink.command(action,a);}else if(action.equals("SetMute")){String v=a.get("DesiredMute");if(!Arrays.asList("0","1","true","false").contains(v))throw new IOException();muted=v.equals("1")||v.equals("true");sink.command(action,a);}r.put("CurrentTransportState",state);r.put("CurrentTransportStatus",status);r.put("CurrentSpeed","1");r.put("Track",uri.isEmpty()?"0":"1");r.put("TrackDuration",time(duration));r.put("TrackMetaData",metadata);r.put("TrackURI",uri);r.put("RelTime",time(position));r.put("AbsTime",time(position));r.put("RelCount","-1");r.put("AbsCount","-1");r.put("NrTracks",uri.isEmpty()?"0":"1");r.put("MediaDuration",time(duration));r.put("CurrentURI",uri);r.put("CurrentURIMetaData",metadata);r.put("NextURI","");r.put("NextURIMetaData","");r.put("PlayMedium","NETWORK");r.put("RecordMedium","NOT_IMPLEMENTED");r.put("WriteStatus","NOT_IMPLEMENTED");r.put("PlayMedia","NETWORK");r.put("RecMedia","NOT_IMPLEMENTED");r.put("RecQualityModes","NOT_IMPLEMENTED");r.put("PlayMode","NORMAL");r.put("RecQualityMode","NOT_IMPLEMENTED");r.put("Actions",uri.isEmpty()?"":"Play,Pause,Stop,Seek");r.put("CurrentVolume",String.valueOf(volume));r.put("CurrentMute",muted?"1":"0");r.put("Source","");r.put("Sink",SINK);r.put("ConnectionIDs","0");r.put("RcsID","0");r.put("AVTransportID","0");r.put("ProtocolInfo","");r.put("PeerConnectionManager","");r.put("PeerConnectionID","-1");r.put("Direction","Input");r.put("Status","OK");return r;}
 static long parseTime(String value)throws Exception{String[] parts=value.split(":");if(parts.length!=3)throw new IOException();long hours=Long.parseLong(parts[0]),minutes=Long.parseLong(parts[1]);double seconds=Double.parseDouble(parts[2]);if(hours<0||hours>10000||minutes<0||minutes>59||seconds<0||seconds>=60||Double.isNaN(seconds))throw new IOException();return hours*3600000L+minutes*60000L+(long)(seconds*1000);}
 static String time(long ms){long s=Math.max(0,ms)/1000;return String.format(Locale.US,"%02d:%02d:%02d",s/3600,s/60%60,s%60);}static String envelope(String body){return "<?xml version='1.0'?><s:Envelope xmlns:s='http://schemas.xmlsoap.org/soap/envelope/' s:encodingStyle='http://schemas.xmlsoap.org/soap/encoding/'><s:Body>"+body+"</s:Body></s:Envelope>";}static String fault(int code,String text){return envelope("<s:Fault><faultcode>s:Client</faultcode><faultstring>UPnPError</faultstring><detail><UPnPError xmlns='urn:schemas-upnp-org:control-1-0'><errorCode>"+code+"</errorCode><errorDescription>"+esc(text)+"</errorDescription></UPnPError></detail></s:Fault>");}
 String device(){StringBuilder list=new StringBuilder();for(String id:new String[]{"avt","rc","cm"})list.append("<service><serviceType>").append(urn(id)).append("</serviceType><serviceId>urn:upnp-org:serviceId:").append(service(id)).append("</serviceId><SCPDURL>/").append(id).append("/scpd.xml</SCPDURL><controlURL>/").append(id).append("/control</controlURL><eventSubURL>/").append(id).append("/event</eventSubURL></service>");return "<?xml version='1.0'?><root xmlns='urn:schemas-upnp-org:device-1-0'><specVersion><major>1</major><minor>0</minor></specVersion><URLBase>"+base+"/</URLBase><device><deviceType>urn:schemas-upnp-org:device:MediaRenderer:1</deviceType><friendlyName>"+esc(name)+"</friendlyName><manufacturer>Sky Family</manufacturer><modelName>Sky Family Frame</modelName><UDN>"+uuid+"</UDN><serviceList>"+list+"</serviceList></device></root>";}
 String datatype(String key){if(key.equals("InstanceID")||key.equals("Track")||key.equals("NrTracks"))return "ui4";if(key.contains("Volume"))return "ui2";if(key.contains("Mute"))return "boolean";if(key.equals("ConnectionID")||key.equals("RcsID")||key.equals("AVTransportID")||key.equals("PeerConnectionID")||key.equals("RelCount")||key.equals("AbsCount"))return "i4";return "string";}
 String scpd(String id){StringBuilder actions=new StringBuilder(),states=new StringBuilder();LinkedHashSet<String> variables=new LinkedHashSet<>();for(String definition:spec(id).split(";")){int colon=definition.indexOf(':');String action=definition.substring(0,colon);String[] sides=definition.substring(colon+1).split(">",-1);actions.append("<action><name>").append(action).append("</name><argumentList>");for(int side=0;side<2;side++)if(side<sides.length&&!sides[side].isEmpty())for(String arg:sides[side].split(",")){variables.add(arg);actions.append("<argument><name>").append(arg).append("</name><direction>").append(side==0?"in":"out").append("</direction><relatedStateVariable>").append(arg).append("</relatedStateVariable></argument>");}actions.append("</argumentList></action>");}for(String v:variables)states.append("<stateVariable sendEvents='no'><name>").append(v).append("</name><dataType>").append(datatype(v)).append("</dataType></stateVariable>");if(!id.equals("cm"))states.append("<stateVariable sendEvents='yes'><name>LastChange</name><dataType>string</dataType></stateVariable>");else for(String v:new String[]{"SourceProtocolInfo","SinkProtocolInfo","CurrentConnectionIDs"})states.append("<stateVariable sendEvents='yes'><name>").append(v).append("</name><dataType>string</dataType></stateVariable>");return "<?xml version='1.0'?><scpd xmlns='urn:schemas-upnp-org:service-1-0'><specVersion><major>1</major><minor>0</minor></specVersion><actionList>"+actions+"</actionList><serviceStateTable>"+states+"</serviceStateTable></scpd>";}
 static class Subscription{String sid,id;URI callback;InetAddress peer;long expires,seq=0;String last="";}
 void subscribe(Socket socket,String id,String method,Map<String,String> h)throws Exception{String sid=h.get("sid");Subscription sub=sid==null?null:subscriptions.get(sid);if(sub!=null&&(!sub.peer.equals(socket.getInetAddress())||!sub.id.equals(id)))sub=null;if(method.equals("UNSUBSCRIBE")){if(sub==null){reply(socket,412,"",null);return;}subscriptions.remove(sub.sid);reply(socket,200,"",null);return;}if(sid!=null&&sub==null){reply(socket,412,"",null);return;}if(sub==null){if(subscriptions.size()>=8||!"upnp:event".equalsIgnoreCase(h.get("nt"))){reply(socket,412,"",null);return;}String cb=h.get("callback");if(cb==null||!cb.startsWith("<")||!cb.endsWith(">")){reply(socket,412,"",null);return;}URI callback=new URI(cb.substring(1,cb.length()-1));if(!"http".equalsIgnoreCase(callback.getScheme())||callback.getHost()==null||callback.getUserInfo()!=null||!InetAddress.getByName(callback.getHost()).equals(socket.getInetAddress())){reply(socket,412,"",null);return;}sub=new Subscription();sub.sid="uuid:"+UUID.randomUUID();sub.id=id;sub.callback=callback;sub.peer=socket.getInetAddress();subscriptions.put(sub.sid,sub);}int timeout=300;String requested=h.get("timeout");if(requested!=null&&requested.startsWith("Second-"))try{timeout=Math.max(30,Math.min(600,Integer.parseInt(requested.substring(7))));}catch(Exception ignored){}sub.expires=System.currentTimeMillis()+timeout*1000L;HashMap<String,String> response=new HashMap<>();response.put("SID",sub.sid);response.put("TIMEOUT","Second-"+timeout);reply(socket,200,"",response);}
 String event(String id){String props;if(id.equals("cm"))props="<e:property><SourceProtocolInfo></SourceProtocolInfo></e:property><e:property><SinkProtocolInfo>"+esc(SINK)+"</SinkProtocolInfo></e:property><e:property><CurrentConnectionIDs>0</CurrentConnectionIDs></e:property>";else{String values=id.equals("avt")?"<TransportState val='"+state+"'/><TransportStatus val='"+status+"'/><TransportPlaySpeed val='1'/><AVTransportURI val='"+esc(uri)+"'/><CurrentTrackDuration val='"+time(duration)+"'/>":"<Volume channel='Master' val='"+volume+"'/><Mute channel='Master' val='"+(muted?1:0)+"'/>";String change="<Event xmlns='urn:schemas-upnp-org:metadata-1-0/"+(id.equals("avt")?"AVT":"RCS")+"/'><InstanceID val='0'>"+values+"</InstanceID></Event>";props="<e:property><LastChange>"+esc(change)+"</LastChange></e:property>";}return "<e:propertyset xmlns:e='urn:schemas-upnp-org:event-1-0'>"+props+"</e:propertyset>";}
 void events(){long now=System.currentTimeMillis();for(Subscription s:subscriptions.values()){if(s.expires<now){subscriptions.remove(s.sid);continue;}String data=event(s.id);if(data.equals(s.last))continue;s.last=data;long seq=s.seq;s.seq=(s.seq+1)&0xffffffffL;try{notifications.execute(()->notify(s,data,seq));}catch(RejectedExecutionException ignored){}}}
 void notify(Subscription s,String xml,long seq){try(Socket socket=new Socket()){int port=s.callback.getPort()<0?80:s.callback.getPort();socket.connect(new InetSocketAddress(s.peer,port),2000);socket.setSoTimeout(2000);String path=s.callback.getRawPath();if(path==null||path.isEmpty())path="/";if(s.callback.getRawQuery()!=null)path+="?"+s.callback.getRawQuery();byte[] body=xml.getBytes("UTF-8");String request="NOTIFY "+path+" HTTP/1.1\r\nHOST: "+s.callback.getHost()+":"+port+"\r\nCONTENT-TYPE: text/xml; charset=utf-8\r\nNT: upnp:event\r\nNTS: upnp:propchange\r\nSID: "+s.sid+"\r\nSEQ: "+seq+"\r\nCONTENT-LENGTH: "+body.length+"\r\nCONNECTION: close\r\n\r\n";socket.getOutputStream().write(request.getBytes("UTF-8"));socket.getOutputStream().write(body);socket.getOutputStream().flush();line(socket.getInputStream());}catch(Exception e){subscriptions.remove(s.sid);}}
 void close(){if(!running)return;running=false;timer.shutdownNow();try{http.close();}catch(Exception ignored){}for(Socket s:sockets)try{s.close();}catch(Exception ignored){}clients.shutdownNow();notifications.shutdownNow();subscriptions.clear();new Thread(()->{announce("ssdp:byebye");discovery.close();},"sky-dlna-close").start();if(multicast!=null&&multicast.isHeld())try{multicast.release();}catch(Exception ignored){}}
